        for faces in range(1, MAX_DICE_THROW_FACES + 1):
            for dice in range(1, MAX_DICE_THROW_DICE + 1):
                for target in range(MAX_DICE_THROW_TARGET + 1):
                    values = (faces, dice, target)
                    cases[values] = oracle(algorithm, list(values))
