            (), (6,), (6, 2), (6, 2, 7, 0),
            (0, 1, 1), (MAX_DICE_THROW_FACES + 1, 1, 1),
            (6, 0, 1), (6, MAX_DICE_THROW_DICE + 1, 1),
            (6, 2, -1), (6, 2, MAX_DICE_THROW_TARGET + 1),
