            for byte in text:
                if 65 <= byte <= 90:
                    seen |= 1 << (byte - 65)
                elif 97 <= byte <= 122:
                    seen |= 1 << (byte - 97)
            missing = MAX_LIPOGRAM_MISSING_MASK ^ seen
