            [1, 0, 1], [1, 0, 1, 5, 1, -1],
            [1, 0, 1, 1_000_001, -1, -1], [1, 0, 1, 5, 0, -1],
            [128, 0, 0], [-1, 0, 0], [1, 0, -1_000_001, 5, -1, -1],
